#!/usr/bin/env python3
"""Export Natlys errands and bilingual copy; lost-property state is runtime quest meta."""
from pathlib import Path
import argparse,csv,io
from build_festivals import lua,KEEP
ROOT=Path(__file__).resolve().parents[3]
AUTHORS={
'ghostfam_garn':dict(npc='ghostfam_dyne',hearts=2,title=['Garn til Dyne','Yarn for Dyne'],desc=['Dyne mangler tre stykker uld til en blå strikbluse.','Dyne needs three pieces of wool for a blue knitted shirt.'],offer=['Vil du hente lidt uld? Så lærer garnet en ny farve.','Will you bring some wool? Then the yarn can learn a new colour.'],choice=['Hent uld til Dyne.','Bring wool to Dyne.'],needs={'wool':3},reward={'items':{'shirt_knit_blue':1},'friendship':{'ghostfam_dyne':1}}),
'ghostfam_lygtemager':dict(npc='ghostfam_gnist',hearts=3,title=['Lygtemagerens prøve','The lantern maker’s test'],desc=['Gnist skal bruge tre lysende svampe og en natblomst.','Gnist needs three glow mushrooms and a night bloom.'],offer=['Vil du hjælpe med en blanding, der lyser stille?','Will you help with a mixture that shines quietly?'],choice=['Hjælp Gnist med lyset.','Help Gnist with the light.'],needs={'glow_mushroom':3,'night_bloom':1},reward={'gold':120,'items':{'lantern_oil':3}}),
'ghostfam_hittegods':dict(npc='ghostfam_silke',hearts=4,title=['Silkes hittegods','Silke’s lost property'],desc=['Silke har fundet en lille ting på sin runde. Hjælp den hjem til ejeren.','Silke found a small item on her round. Help it home to its owner.'],offer=['Der ligger noget i min kurv, som nogen savner. Vil du hjælpe?','There is something in my basket that somebody is missing. Will you help?'],choice=['Hjælp med hittegodset.','Help with the lost property.'],needs={},reward={'gold':60})}
LOST=[('guard_oak','apple','Oak','et æble','an apple'),('pippin_boegeknop','cookie','Pippin','en småkage','a cookie'),('fairy_lily','wild_flower','Lily','en vild blomst','a wild flower'),('carpenter_brumme','rope','Brumme','et reb','a rope'),('bathkeeper_sofus','honey','Sofus','en krukke honning','a jar of honey'),('appraiser_fru_ugle','moss','Fru Ugle','noget mos','some moss')]
def build():
 rows=[];files={}
 for q,a in AUTHORS.items():
  prefix='QUEST_'+q.upper()+'_'
  for key,field in [('TITLE','title'),('DESC','desc'),('OFFER','offer'),('CHOICE','choice')]:rows.append([prefix+key,*a[field]])
  objs=[]
  for item,n in a['needs'].items():
   key='OBJ_'+q.upper()+'_'+item.upper()
   label={'wool':['Saml tre stykker uld.','Collect three pieces of wool.'],'glow_mushroom':['Saml tre lysende svampe.','Collect three glow mushrooms.'],'night_bloom':['Find en natblomst.','Find a night bloom.']}[item]
   rows.append([key,*label]);objs.append({'id':item,'target':n,'on':'item_gained','item':item,'have':True,'description_key':key})
  key='OBJ_'+q.upper()+'_RETURN'
  rows.append([key,'Giv hittegodset til ejeren.' if not a['needs'] else 'Tag tingene med tilbage.','Give the lost item to its owner.' if not a['needs'] else 'Bring the items back.'])
  objs.append({'id':'return','target':1,'on':'manual','description_key':key} if not a['needs'] else {'id':'return','target':1,'on':'dialogue_started','npc':a['npc'],'after_others':True,'needs':a['needs'],'consume':True,'description_key':key})
  meta={'giver':a['npc'],'location':'ZONE_CITY','category':'errand','tag':'VENSKAB','repeatable':q=='ghostfam_hittegods','cooldown_days':7 if q=='ghostfam_hittegods' else 0}
  text='-- Generated by tools/social/content/build_family_quests.py.\nkind = "quest"\nid = "'+q+'"\nobjectives = '+lua(objs)+'\nrewards = '+lua(a['reward'])+'\nmeta = '+lua(meta)+'\n\nfunction is_available(context)\n  return api.get_hearts("'+a['npc']+'") >= '+str(a['hearts'])+'\nend\n\nfunction on_offer(context)\n  return { available = true, text_key = "'+prefix+'OFFER" }\nend\n'
  files[ROOT/'lua/quests'/(q+'.lua')]=text
 lost=[]
 for npc,item,name,da_item,en_item in LOST:
  key='OBJ_GHOSTFAM_HITTEGODS_RETURN_'+npc.upper()
  rows.append([key,f'Giv {da_item} fra Silke til {name}.',f'Give {en_item} from Silke to {"Fru Ugle" if name=="Fru Ugle" else name}.'])
  lost.append({'owner':npc,'item':item,'objective_key':key})
 files[ROOT/'lua/config/ghostfam_quests.lua']='-- The eligible owners are filtered against NpcDirector at offer/accept time.\nkind = "config"\nconfig = { ghostfam_quests = { lost = '+lua(lost)+' } }\n'
 rows += [['GF_QUEST_PARCEL_WAIT','Silke gemmer tingen, til du har plads. Tal med hende igen.','Silke keeps the item until you have room. Speak with her again.'],['GF_QUEST_PARCEL_TITLE','Silkes kurv','Silke’s basket']]
 out=io.StringIO(newline='');w=csv.writer(out,lineterminator='\n');w.writerow(['keys','da','en']);w.writerows(rows)
 files[ROOT/'localization/ghostfamily_quests.csv']=out.getvalue()
 for p in list(files):files[p.with_suffix(p.suffix+'.import')]=KEEP
 return files

def main():
 ap=argparse.ArgumentParser();ap.add_argument('--check',action='store_true');args=ap.parse_args();stale=[]
 for p,data in build().items():
  if args.check:
   if not p.exists() or p.read_text()!=data:stale.append(str(p.relative_to(ROOT)))
  else:p.parent.mkdir(parents=True,exist_ok=True);p.write_text(data)
 if stale:raise SystemExit('stale: '+', '.join(stale))
 print('Natlys quest content '+('verified' if args.check else 'exported'))
if __name__=='__main__':main()
